 names=[f'{v} tetrahedron {n}bp' for v in ['FV','MV'] for n in [42,63,84]]+['FV octahedron84bp','MV octahedron84bp','FV pentagonal bipyramid42bp','MV asymmetric tetrahedron42/69/69/103/103/130bp']
